const BF_VB = "380 280 1240 1440";
const REDUCED = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const easeIO = t => t<.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2;
const lerpPts = (a,b,t) => { let d=""; for(let i=0;i<a.length;i+=2){ d += (i?" ":"M")+((1-t)*a[i]+t*b[i]).toFixed(1)+" "+((1-t)*a[i+1]+t*b[i+1]).toFixed(1); } return d+"Z"; };
const ptsPath = p => { let d=""; for(let i=0;i<p.length;i+=2){ d += (i?" ":"M")+p[i]+" "+p[i+1]; } return d+"Z"; };
function butterflyMarkup(){
  const P="#945777", Y="#FFD468";
  return `<path class="bfn" fill="${P}"/><path class="bfw" fill="#FFFFFF"/>`
       + M3.ant.map(()=>`<path class="bat" fill="${P}"/>`).join("")
       + M3.covers.map(()=>`<path class="bcv" fill="${Y}" stroke="${P}" stroke-width="30" stroke-linejoin="round"/>`).join("")
       + M3.face.map(()=>`<path class="bfc" fill="${P}"/>`).join("");
}
function bindButterfly(g){
  const fan=g.querySelector(".bfn"), fanW=g.querySelector(".bfw"), ant=[...g.querySelectorAll(".bat")], cov=[...g.querySelectorAll(".bcv")], fac=[...g.querySelectorAll(".bfc")];
  let last=-1;
  return function set(t){
    if(Math.abs(t-last)<0.003) return; last=t;
    fan.setAttribute("d", lerpPts(M3.fan[0].a,M3.fan[0].b,t));
    fanW.setAttribute("d", M3.fan.slice(1).map(f=>lerpPts(f.a,f.b,t)).join(""));
    M3.ant.forEach((f,i)=>ant[i].setAttribute("d", lerpPts(f.a,f.b,t)));
    M3.covers.forEach((f,i)=>cov[i].setAttribute("d", lerpPts(f.a,f.b,t)));
    M3.face.forEach((f,i)=>fac[i].setAttribute("d", lerpPts(f.a,f.b,t)));
  };
}
class Butterfly {
  constructor(host, mode){
    this.host=host; this.mode=mode; this.phase=Math.random()*3000; this.hover=false;
    host.innerHTML = `<svg viewBox="${BF_VB}" aria-hidden="true"><g>${butterflyMarkup()}</g></svg>`;
    this.set = bindButterfly(host.querySelector("g")); this.set(0);
    if(mode==="hover"){ host.addEventListener("pointerenter",()=>{this.hover=true}); host.addEventListener("pointerleave",()=>{this.hover=false}); }
    BFS.push(this);
  }
  tick(now){
    if(REDUCED || this.mode==="still") return;
    if(this.mode==="hover"){ const u=((now+this.phase)%620)/620; this.set(this.hover ? (0.5-0.5*Math.cos(u*6.283))*0.6 : 0); return; }
    const period=3200, u=((now+this.phase)%period)/period;
    const f = u<0.72 ? 0 : Math.sin((u-0.72)/0.28*Math.PI);
    this.set(easeIO(f)*0.55);
  }
}
const BFS=[];
document.querySelectorAll("[data-butterfly]").forEach(el => new Butterfly(el, el.dataset.butterfly||"idle"));
document.querySelectorAll("[data-wordmark]").forEach(el => { el.innerHTML = WM[el.dataset.wordmark]; });

