    const by = m*m*m*P0.y + 3*m*m*e*P1.y + 3*m*e*e*P2.y + e*e*e*P3.y;
    const vx = 3*m*m*(P1.x-P0.x) + 6*m*e*(P2.x-P1.x) + 3*e*e*(P3.x-P2.x);
    const vy = 3*m*m*(P1.y-P0.y) + 6*m*e*(P2.y-P1.y) + 3*e*e*(P3.y-P2.y);
